  // Assistant
  'Assistant E-Scolarité': { wo: 'Ndimbalukaayu E-Scolarité', en: 'E-Scolarité Assistant', ar: 'مساعد E-Scolarité' },
  'Bonjour 👋 Je suis votre assistant E‑Scolarité. Comment puis-je vous aider ?': { wo: 'Jàmm nga am 👋 Man maay sa ndimbalukaayu E‑Scolarité. Naka laa la mëna dimbali?', en: 'Hello 👋 I’m your E‑Scolarité assistant. How can I help?', ar: 'مرحباً 👋 أنا مساعد E‑Scolarité. كيف يمكنني مساعدتك؟' },
  'Je peux vous aider à analyser les souscriptions, configurer une offre ou retrouver un établissement.': { wo: 'Mën naa la dimbali nga saytu bëgg-bëgg yi, tëral offre walla gis ekool.', en: 'I can help analyze subscriptions, configure a plan or find an institution.', ar: 'يمكنني مساعدتك في تحليل الاشتراكات أو إعداد عرض أو العثور على مؤسسة.' },
  'Je peux rédiger un contenu, préparer une actualité ou vous guider dans la publication du site.': { wo: 'Mën naa bind ëmbiit, waajal xibaar walla gindi la ci siib siti bi.', en: 'I can write content, prepare news or guide you through publishing the website.', ar: 'يمكنني كتابة محتوى أو إعداد خبر أو إرشادك في نشر الموقع.' },
  'Je peux vous assister pour les inscriptions, les paiements, les absences et les communications aux familles.': { wo: 'Mën naa la dimbali ci bind, fay, ñàkk ak jokkoo ak njaboot yi.', en: 'I can help with enrollments, payments, attendance and family communications.', ar: 'يمكنني مساعدتك في التسجيلات والمدفوعات والغياب والتواصل مع الأسر.' },
  'Je peux vous présenter E‑Scolarité et vous orienter vers les fonctionnalités adaptées à votre établissement.': { wo: 'Mën naa la won E‑Scolarité te gindi la ci mën-mën yi méngoo ak sa ekool.', en: 'I can introduce E‑Scolarité and guide you to features suited to your institution.', ar: 'يمكنني تعريفك بـ E‑Scolarité وتوجيهك إلى الميزات المناسبة لمؤسستك.' },
  'Disponible pour vous aider': { wo: 'Jàppandi na ngir dimbali la', en: 'Available to help', ar: 'متاح لمساعدتك' },
  'Fermer l’assistant': { wo: 'Tëj ndimbalukaay bi', en: 'Close assistant', ar: 'إغلاق المساعد' },
