export function translatePlatformText(
  value: string,
  locale: PlatformLocale,
): string {
  if (locale === 'fr') {
    return value;
  }

  const exact = PLATFORM_TRANSLATIONS[value]?.[locale];
  if (exact) {
    return exact;
  }

  if (value.includes(' · ')) {
    const translatedParts = value
      .split(' · ')
      .map((part) => translatePlatformText(part, locale));
    const compound = translatedParts.join(' · ');
    if (compound !== value) {
      return compound;
    }
  }

  const colonPhrase = value.match(/^(.+?)\s*:\s*(.+)$/);
  if (colonPhrase && PLATFORM_TRANSLATIONS[colonPhrase[1]]) {
    return `${PLATFORM_TRANSLATIONS[colonPhrase[1]][locale]} : ${colonPhrase[2]}`;
  }

  const prefixKey = Object.keys(PLATFORM_TRANSLATIONS)
    .filter(
      (key) =>
        value.startsWith(`${key} `) &&
        (key.includes(' ') || key === 'Mensualité' || key === 'Objectif' || key === 'Année'),
    )
    .sort((a, b) => b.length - a.length)[0];
  if (prefixKey) {
    return `${PLATFORM_TRANSLATIONS[prefixKey][locale]}${value.slice(prefixKey.length)}`;
  }

  const numberedPhrase = value.match(/^([+−-]?\d[\d\s.,]*%?)\s+(.+)$/);
  if (numberedPhrase) {
    const translatedSuffix = translatePlatformText(numberedPhrase[2], locale);
    if (translatedSuffix !== numberedPhrase[2]) {
      return `${numberedPhrase[1]} ${translatedSuffix}`;
    }
  }

  const room = value.match(/^Salle\s+(.+)$/i);
  if (room) {
    const roomLabel: Translations = { wo: 'Sàll', en: 'Room', ar: 'القاعة' };
    return `${roomLabel[locale]} ${room[1]}`;
  }

  if (value === '/ mois') {
    const monthly: Translations = { wo: '/ weer', en: '/ month', ar: '/ شهر' };
    return monthly[locale];
  }

  const toggle = value.match(/^Activer ou désactiver\s+(.+)$/);
  if (toggle) {
    const translatedType = translatePlatformText(toggle[1], locale);
    const prefix: Translations = {
      wo: 'Tàmbali walla taxawal',
      en: 'Enable or disable',
      ar: 'تفعيل أو تعطيل',
    };
    return `${prefix[locale]} ${translatedType}`;
  }

  const estimatedValue = value.match(/^Valeur estimée\s*:\s*(.+)$/);
  if (estimatedValue) {
    const prefix: Translations = {
      wo: 'Njëg bu ñu xayma',
      en: 'Estimated value',
      ar: 'القيمة المقدرة',
    };
    return `${prefix[locale]} : ${estimatedValue[1]}`;
  }

  const numberUnit = value.match(/^(\d[\d\s.,]*)\s+(élèves|classes|matières|enseignants|campus|modules|apprenants|établissements|clients actifs|séance|séances|présent|présents|absent|absents|retard|retards)$/i);
  if (numberUnit) {
    const units: Record<string, Translations> = {
      élèves: { wo: 'taalibe', en: 'students', ar: 'تلميذاً' },
      classes: { wo: 'kalaas', en: 'classes', ar: 'أقسام' },
      matières: { wo: 'mbaar', en: 'subjects', ar: 'مواد' },
      enseignants: { wo: 'jàngalekat', en: 'teachers', ar: 'معلماً' },
      campus: { wo: 'campus', en: 'campuses', ar: 'فروع' },
      modules: { wo: 'modil', en: 'modules', ar: 'وحدات' },
      apprenants: { wo: 'jàngkat', en: 'learners', ar: 'متعلماً' },
      établissements: { wo: 'ekool', en: 'institutions', ar: 'مؤسسات' },
      'clients actifs': { wo: 'kiliyaan yiy dox', en: 'active clients', ar: 'عملاء نشطين' },
      séance: { wo: 'waxtu njàng', en: 'session', ar: 'حصة' },
      séances: { wo: 'waxtuy njàng', en: 'sessions', ar: 'حصص' },
      présent: { wo: 'ku teewe', en: 'present', ar: 'حاضر' },
      présents: { wo: 'ñu teewe', en: 'present', ar: 'حاضرين' },
      absent: { wo: 'ku ñàkk', en: 'absent', ar: 'غائب' },
      absents: { wo: 'ñu ñàkk', en: 'absent', ar: 'غائبين' },
      retard: { wo: 'ku yeex', en: 'late', ar: 'متأخر' },
      retards: { wo: 'ñu yeex', en: 'late', ar: 'متأخرين' },
    };
    return `${numberUnit[1]} ${units[numberUnit[2].toLowerCase()]?.[locale] ?? numberUnit[2]}`;
  }

  return value;
}
